// 计算一个数的因子2的个数
int countFactorsOf2(int x) {
    int cnt = 0;
    while (x % 2 == 0) {
        cnt++;
        x /= 2;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
