    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // 原始每个数的因子2个数及总和
    int total = 0;
    vector<int> base(n);
    for (int i = 0; i < n; i++) {
        base[i] = countFactorsOf2(a[i]);
        total += base[i];
    }

    // 计算每个数加1后的增量（非负）
    vector<int> gains(n);
    for (int i = 0; i < n; i++) {
        int orig = countFactorsOf2(a[i]);
        int newVal = countFactorsOf2(a[i] + 1);
        int gain = newVal - orig;
        gains[i] = (gain > 0) ? gain : 0;
    }

    // 降序排序
    sort(gains.begin(), gains.end(), greater<int>());

